#!/usr/bin/env python3
import argparse
import csv


SPECIES = ["human", "mouse", "pig"]


def rounded10(counts):
    total = sum(counts.values())
    if not total:
        return {sp: 0 for sp in SPECIES}
    raw = {sp: counts[sp] * 100.0 / total for sp in SPECIES}
    out = {sp: int(round(raw[sp] / 10.0) * 10) for sp in SPECIES}
    diff = 100 - sum(out.values())
    if diff:
        order = sorted(SPECIES, key=lambda sp: raw[sp] - out[sp], reverse=(diff > 0))
        step = 10 if diff > 0 else -10
        for sp in order:
            if diff == 0:
                break
            out[sp] += step
            diff -= step
    return out


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("barcodes")
    parser.add_argument("out")
    args = parser.parse_args()
    rows = []
    with open(args.barcodes, newline="") as handle:
        reader = csv.DictReader(handle, delimiter="\t")
        for row in reader:
            row["total_umis"] = int(row["total_umis"])
            for sp in SPECIES:
                row[sp + "_umis"] = int(row[sp + "_umis"])
            row["top_fraction"] = float(row["top_fraction"])
            rows.append(row)

    with open(args.out, "w") as out:
        out.write("min_top_umis\tmin_fraction\thuman\tmouse\tpig\thuman_pct\tmouse_pct\tpig_pct\trounded\n")
        for min_top in [1, 3, 5, 10, 20, 50]:
            for min_frac in [0.8, 0.9, 0.95]:
                counts = {sp: 0 for sp in SPECIES}
                for row in rows:
                    top = row["top_species"]
                    if row[top + "_umis"] >= min_top and row["top_fraction"] >= min_frac:
                        counts[top] += 1
                total = sum(counts.values()) or 1
                r = rounded10(counts)
                out.write(
                    f"{min_top}\t{min_frac:.2f}\t{counts['human']}\t{counts['mouse']}\t{counts['pig']}"
                    f"\t{counts['human'] * 100.0 / total:.2f}\t{counts['mouse'] * 100.0 / total:.2f}"
                    f"\t{counts['pig'] * 100.0 / total:.2f}\t{r['human']};{r['mouse']};{r['pig']}\n"
                )


if __name__ == "__main__":
    main()

